import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%90%E3%82%A4%E3%82%AF.html","title":"バイク","lang":"en-US","frontmatter":{},"git":{"createdTime":1652074565000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":20}]},"readingTime":{"minutes":2.89,"words":868},"filePathRelative":"バイク.md"}`),a={name:`バイク.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="バイク" tabindex="-1"><a class="header-anchor" href="#バイク"><span>バイク</span></a></h1><p>バイク関連のグッズをまとめるページ。<a href="./電動アシスト自転車.html">電動アシスト自転車</a></p><h2 id="dio-110" tabindex="-1"><a class="header-anchor" href="#dio-110"><span>Dio 110</span></a></h2><p><a href="./Dio110.html">Dio110</a></p><h2 id="ファスナー無しポンチョ-2026-06-20-土" tabindex="-1"><a class="header-anchor" href="#ファスナー無しポンチョ-2026-06-20-土"><span>ファスナー無しポンチョ 2026-06-20 (土)</span></a></h2><p>ファスナーをしめるのが意外と引っかからないようにするのが面倒なので、ファスナー無しのポンチョをポチってみる。</p><p><a href="https://a.r10.to/hgUOKN" target="_blank" rel="noopener noreferrer">楽天: ポンチョ型レインコート</a></p><p>たぶん同じものがAmazonでも売っていて、両者のレビューを総合してこれにしてみる。 ちょうど20%オフだったので3984円。 この辺で梅雨の出不精が減らせられたらいいな、という事で。</p><h3 id="手軽で良い-2026-06-25-木" tabindex="-1"><a class="header-anchor" href="#手軽で良い-2026-06-25-木"><span>手軽で良い 2026-06-25 (木)</span></a></h3><p>雨が降っていたので試してみた。やはり着脱はジッパータイプよりずっと楽。</p><p>60kmくらい出すと多少風ははらむが、走る事は出来る。雨の日に60kmは結構飛ばしている感じなので、まぁこれならいいかな。 バサバサはそんなにしない。これならいいかな。</p><p>Tシャツで羽織ったが、やはり肌に濡れたカッパがつくのは不快感があるので、袖があるシャツの方がいいな。</p><p>靴周りだけちょっと濡れる感じで、他は特に濡れない。たぶん走っているだけなら靴周りも濡れない気はするが、今日は波チェックで長い事停車していたので、 その場合は足先が少し濡れる感じだ。 でも普通に外を傘さして歩く程では無いので、むしろかなり濡れないな、という印象。</p><p>気に入った。やはりジッパー無しの方がスクーター向きだな。</p><h3 id="さらに使って、とても良い-2026-06-28-日" tabindex="-1"><a class="header-anchor" href="#さらに使って、とても良い-2026-06-28-日"><span>さらに使って、とても良い 2026-06-28 (日)</span></a></h3><p>台風の通過で雨が続いたので使う機会が多かったが、凄く良いね、これ。 玄関にかけておいて、さくっと被って出かけてついたら脱ぐと、玄関から目的地までずっと濡れないで行けて、やはりジッパーよりずっと手軽。</p><p>腕の所がゴムでしまってて袖が濡れないのは結構良い。</p><p>足先は少しだけ濡れるが、着替えないと嫌なくらいではないので、まぁいいか、と思える。 走っている時は濡れないので、信号とか次第では全然濡れない。</p><p>ちょっとした距離のお出かけが凄い手軽になった。このポンチョは買って良かった。</p><h2 id="斜めファスナーポンチョ-2026-06-15-月" tabindex="-1"><a class="header-anchor" href="#斜めファスナーポンチョ-2026-06-15-月"><span>斜めファスナーポンチョ 2026-06-15 (月)</span></a></h2><p>スクーターは以前買ったレインスーツ（一つ下の段落に書いてあるやつ）ではなくポンチョの方がいいのでは？と思いつき、以下をポチる。Lを購入。2996円。</p><p><a href="https://www.amazon.co.jp/dp/B0GSVD2BN3?th=1&amp;psc=1&amp;linkCode=ll2&amp;tag=karino203-22&amp;linkId=45abeccdb278b2764533751f0e7f8845&amp;ref_=as_li_ss_tl" target="_blank" rel="noopener noreferrer">amazon: OutRush 斜めファスナーレインコート</a></p><p><a href="./Dio110.html">Dio110</a>は意外と足の前の風防みたいなので雨が当たらないので、上だけカバー出来ればいいんじゃないか、 というのと、カバンを持ったまますぐ着れると良いんじゃないか、というのと、レインスーツは到着したあとにズボンを脱ぐのがかったるいのが外にでなくなる理由なのではないか、という考えによる。</p><p>2026-06-16 (火) に到着。風防がなんかひっかき傷みたいなのが大きく入っている初期不良だったが、風防は使う予定は無いしいいか、と返品はせずにそのままで。前が二重になるのね、良さそう。長さは足りてそうだがバイク乗ってみないと分からないな。</p><h3 id="普通の雨での使用はなかなか良い-2026-06-20-土" tabindex="-1"><a class="header-anchor" href="#普通の雨での使用はなかなか良い-2026-06-20-土"><span>普通の雨での使用はなかなか良い 2026-06-20 (土)</span></a></h3><p>そこまで強い雨という訳ではないが雨降ってる、という感じの日に使ってみた。</p><p>着るのは期待してたほど楽でも無いがレインスーツよりは楽で、まぁいいか、という感じ。 防水能力は十分で、全然濡れない。 足のあたりとかもっと濡れるかと思ったが、やはり<a href="./Dio110.html">Dio110</a>の足元はそもそもあまり濡れないので、 これとポンチョの組合せでは全く濡れなくなる、という事が確認出来た。</p><p>バタつきも意外とバタつかない。それなりの重さがある。 ただ幹線道路などで飛ばすとバタつく。雨の日はそんなに飛ばさないのでこれなら十分実用範囲だな。</p><p>前のボタンを止めないと足元がめくれて出てしまう。着るのかったるいから、と横着して多少後悔した。</p><p>ポンチョと体の間に結構スペースがあるので、着心地は楽。この辺はポンチョに期待していたものなので、かなり満足。</p><p>今日は雨は小雨くらいで降ったりやんだりだから、ポンチョとしての性能はそこまでは問われないが、 実際問題としてこれまでなら外出する気は起きなかったような日なので、 こういう日に外出する気になるというポンチョに期待していた目的は果たしている。 梅雨の時期にも図書館などに行く生活にしたかったのだから、むしろこういう日の性能が重要かもしれない。</p><p>帰りは割とがっつり降ったのでその印象も。</p><p>手と足は濡れる。ズボンも足元は少し濡れるが足元だけ。足はビーサンだし家に帰ったあと少し拭く程度でズボンは着替える程では無いかな、という感じ。傘で歩くよりはだいぶ良いか。 信号などで止まってる時に足を出すので少し足が濡れる感じはあったが、家についてみたら意外と濡れてなかった。</p><p>腕は濡れたビニールが張り付く不快感はあり。上着は着た方がいいな。</p><p>ファスナーは着脱はやはりかったるいな。レインスーツよりはマシだが、意外とファスナーの所は手間取るので、ファスナー無しのポンチョも試したくなった。</p><p>どうせ梅雨の時期は二つくらいあってもいい気がするのでもう一つ買おう。</p><h2 id="レインスーツ-2022-05-09" tabindex="-1"><a class="header-anchor" href="#レインスーツ-2022-05-09"><span>レインスーツ 2022-05-09</span></a></h2><p>これまではホムセンで買った雨合羽を使っていたが、そろそろ寿命だったのもあり、 少しいいヤツにしてみよう、という事で楽天を物色。 以下を買う。</p><p><a href="https://hb.afl.rakuten.co.jp/ichiba/276c9280.0c50a22c.276c9281.538d72d2/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Fhatoya-2%2Fsm20210416001%2F&amp;link_type=pict&amp;ut=eyJwYWdlIjoiaXRlbSIsInR5cGUiOiJwaWN0Iiwic2l6ZSI6IjI0MHgyNDAiLCJuYW0iOjEsIm5hbXAiOiJyaWdodCIsImNvbSI6MSwiY29tcCI6ImRvd24iLCJwcmljZSI6MSwiYm9yIjoxLCJjb2wiOjEsImJidG4iOjEsInByb2QiOjAsImFtcCI6ZmFsc2V9" target="_blank" rel="nofollow sponsored noopener" style="word-wrap:break-word;">HATOYA: HR-002 軽量ストレッチレインスーツ<br><img src="https://hbb.afl.rakuten.co.jp/hgb/276c9280.0c50a22c.276c9281.538d72d2/?me_id=1389765&amp;item_id=11203147&amp;pc=https%3A%2F%2Fthumbnail.image.rakuten.co.jp%2F%400_mall%2Fhatoya-2%2Fcabinet%2Fyamaoka_1%2Fsm20210416001_1.jpg%3F_ex%3D240x240&amp;s=240x240&amp;t=pict" border="0" style="margin:2px;" alt="" title=""></a></p><p>Lのオレンジを買った。 雨の日に使ったら感想を追記していきたい。</p><p><strong>2022-11-29</strong> 帰りに大雨に降られたので性能を試せた。バイクに乗っている間は全く濡れて無くてすごく快適だった。 だが部屋に帰ってからジーンズのモモが少し濡れている事に気づく。短時間なので肌側にはしみてなかっただけかもしれないが、 レインスーツを部屋に持ち込んで干したりしている時に当たってた可能性もあるのでどっちかわからない。</p><p>ただ何にせよ、めちゃくちゃ防水性能は高く、蒸れずにとても快適だった。普通の雨だったら全然平気そうね。買ってよかった。</p><h2 id="グローブ" tabindex="-1"><a class="header-anchor" href="#グローブ"><span>グローブ</span></a></h2><p>グローブは普段は使わないで雨の日専用のを買いたくて、以下をポチる。(2022-05-09）</p><p><a href="https://www.yodobashi.com/product/100000001003372551/" target="_blank" rel="noopener noreferrer">ヨドバシ：DAYTONA デイトナ RIDEMITT ＃003 ネオプレン 防水グローブ Sサイズ ブラック</a></p><p>楽天やAmazonを見てRIDEMITT 003が良さそうと思ったが、送料を考えるとヨドが安かったのでヨドで。 ただ間違ってSを買ってしまった。 装着すると指の長さは足りているので別にSでも良い気はするが、ちょっと締め付ける感じはある。 伸長170cmの自分にはMくらいがベストサイズだったかもしれない。</p><p>しばらく使った感想。やはりキツい。ただ全然濡れない。 雨の日になんか雨嫌だなぁ、という気分の時にはこれを使うと雨の嫌さはだいぶ無くなる。 別に濡れてもいいか、と思っている時は大げさかなぁ、とも思うが、 持っておくといい気はしている。</p><h2 id="ダイソーの靴用レインカバー" tabindex="-1"><a class="header-anchor" href="#ダイソーの靴用レインカバー"><span>ダイソーの靴用レインカバー</span></a></h2><p>この前バイク屋に持っていった時に結構ひどい雨に降られたのだが、 ダイソーで買った靴用レインカバー的なのが非常に良くて、足が全然濡れなかった。 しかもビニール袋と違ってちゃんと靴底があるので歩いたりバイク操作にも支障がない。</p><p>かっぱと手袋は雨がしみていまいちだったが、靴が濡れないならこの辺ももうちょっと良いのを装備すれば雨でも走れるのでは無いか？ と思い、上のレインスーツを買ってみたりした。</p><h2 id="ハンドルバーバッグ" tabindex="-1"><a class="header-anchor" href="#ハンドルバーバッグ"><span>ハンドルバーバッグ</span></a></h2><p>以下をポチる。(2025-09-19 (金))</p><p><a href="https://amzn.to/46sisIV" target="_blank" rel="noopener noreferrer">amazon: ROCKBROS バイク バッグ</a></p><p>3180円だった。</p><h3 id="第一印象-2025-09-20-土" tabindex="-1"><a class="header-anchor" href="#第一印象-2025-09-20-土"><span>第一印象 2025-09-20 (土)</span></a></h3><p>届いたのでつけて軽く走ってきた。心配だった<a href="./Dio110.html">Dio110</a>につくのか、という所はバッチリついた。ちょうどいい感じだね。 軽く走ってみると、つけた状態で走るのは特に問題もなく、すごくいい感じだ。</p><p>一方、外した時に扱いにはやや困る。ちょっとかさばるので。</p><p>つけっぱなしにしてショルダーバッグを突っ込んで使うのがいいか、少し遠くに行く時だけ使うようにするのがいいか、 ちょっと使い方は悩むな。</p><h3 id="しばらく経って、なかなか良いね-2025-11-30-日" tabindex="-1"><a class="header-anchor" href="#しばらく経って、なかなか良いね-2025-11-30-日"><span>しばらく経って、なかなか良いね 2025-11-30 (日)</span></a></h3><p>普段使いには使っていないが、どこかナビを使って出かけたい時などに凄く良い。 ナビとして一番安心して使える。スマホホルダーをつけるよりは断然良いな。 タンクバックの代わりとしてとても良い。</p><p>つけっぱなしにするには邪魔だし持ち歩くのも不便だなぁ、と思っていたが、 それらを理解した上で割り切って使うと、とても満足度が高くなってきた。</p><p>買って良かった。</p><hr><h2 id="vtz-250" tabindex="-1"><a class="header-anchor" href="#vtz-250"><span>VTZ 250</span></a></h2><p>以前のバイク。<a href="./VTZ250.html">VTZ250</a></p>`,65)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};